def draw_bar_chart_UberWithOpenAIBinary():
    labels = ['Relevant', 'Irrelevant']
    human_values = [440, 287]
    llm_values = [502, 225]
    bar_height = 0.35
    y_pos = range(len(labels))

    fig, ax = plt.subplots(figsize=(7, 4.5))
    ax.barh([y + bar_height / 2 for y in y_pos], human_values, height=bar_height, color='red', label='Human')
    ax.barh([y - bar_height / 2 for y in y_pos], llm_values, height=bar_height, color='green', label='LLM')

    for i in range(len(labels)):
        ax.text(human_values[i] + 4, i + bar_height / 2, str(human_values[i]), va='center', fontsize=9)
        ax.text(llm_values[i] + 4, i - bar_height / 2, str(llm_values[i]), va='center', fontsize=9)

    ax.set_yticks(y_pos)
    ax.set_yticklabels(labels, rotation='vertical', fontsize=10)
    ax.invert_yaxis()
    ax.set_xlim([0, max(human_values + llm_values) + 60])
    ax.set_xticks([])
    ax.legend(loc='lower right', frameon=False)
    st.pyplot(fig)


