def confusionMatrixHumanVLLMUBEROpenAIOrdinal():
    global labels, fig, ax
    # Confusion Matrix: Human vs. LLM Sentiment (Detailed)
    conf_matrix = np.array([
        [7, 11, 1, 1, 1],
        [2, 15, 10, 12, 3],
        [2, 9, 90, 37, 32],
        [0, 3, 25, 58, 60],
        [0, 1, 2, 15, 43]
    ])
    labels = [-2, -1, 0, 1, 2]
    df_cm = pd.DataFrame(conf_matrix, index=labels, columns=labels)
    fig, ax = plt.subplots(figsize=(7, 6))
    sns.heatmap(df_cm, annot=True, fmt="d", cmap="Blues", cbar=True, square=True, ax=ax)
    ax.set_xlabel("Predicted label")
    ax.set_ylabel("True label")
    ax.set_title("Confusion Matrix: Human vs. LLM Sentiment")
    st.pyplot(fig)


def distributionOfAbsoluteErrorsUBEROpenAIOrdinal():
    global fig, ax
    # Distribution of Absolute Errors
    # Updated data from image
    errors = [0, 1, 2, 3, 4]
    frequencies = [213, 173, 46, 7, 1]
    # Create plot
    fig, ax = plt.subplots()
    bars = ax.bar(errors, frequencies, color='skyblue', edgecolor='black')
    # Add value labels on top of each bar
    for bar in bars:
        height = bar.get_height()
        ax.annotate(f'{height}',
                    xy=(bar.get_x() + bar.get_width() / 2, height),
                    xytext=(0, 3),  # slight vertical offset
                    textcoords="offset points",
                    ha='center', va='bottom')
    # Set labels and title
    ax.set_title("Distribution of Absolute Errors")
    ax.set_xlabel("Absolute Error")
    ax.set_ylabel("Frequency")
    ax.set_xticks(errors)
    ax.grid(axis='y', linestyle='--', linewidth=0.5, alpha=0.7)
    # Display in Streamlit
    st.pyplot(fig)


